from html.parser import HTMLParser
from pathlib import Path
import re,sys
class Page(HTMLParser):
 def __init__(self):
  super().__init__(); self.skip=False; self.parts=[]
 def handle_starttag(self,tag,attrs):
  if tag in ('script','style'): self.skip=True
 def handle_endtag(self,tag):
  if tag in ('script','style'): self.skip=False
 def handle_data(self,data):
  if not self.skip: self.parts.append(data)
page=Page(); page.feed(Path(sys.argv[1]).read_text())
visible=' '.join(' '.join(page.parts).split())
for m in re.finditer(r'line.items?|sub.?total|CSV|export|net amount|tax amount',visible,re.I):
 print(visible[max(0,m.start()-80):m.end()+95])
